<script setup lang="ts">
import { computed, ref, watch, nextTick } from 'vue';
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import DashboardLayout from '../layouts/DashboardLayout.vue';
import AppIcon from '../components/AppIcon.vue';
import { schoolHref } from '../navigation';
import type { School, SchoolDashboard } from '../types';
type Row = Record<string, any>;
interface Field {key:string;label:string;type:string;source?:string;options?:string[]}
const props=defineProps<{page:string;title:string;fields:Field[];rows:{data:Row[];links:{url:string|null;label:string;active:boolean}[];total:number}|null;roster:Row[];options:Record<string,Row[]>;filters:Row;reports:Row|null;weekly:Row[];baseUrl:string;flash:{success?:string};draftReports:Row[];schools:School[];selectedSchool:School|null;dashboard:SchoolDashboard|null;liveAcademic?:Row|null}>();
const pageState=usePage();
const globalErrors=computed(()=>pageState.props.errors??{});
const query=ref(props.filters.q??''), session=ref(props.filters.academic_session_id??''), section=ref(props.filters.section_id??''), klass=ref(props.filters.academic_class_id??''), teacher=ref(props.filters.teacher_id??''), student=ref(props.filters.student_id??''), exam=ref(props.filters.exam_id??''), schedule=ref(props.filters.exam_schedule_id??''), date=ref(props.filters.attendance_date), from=ref(props.filters.from), to=ref(props.filters.to), reportType=ref(props.filters.report_type??'attendance');
const showForm=ref(false), editId=ref<number|null>(null), deleting=ref<Row|null>(null);
let dialogOpener:HTMLElement|null=null;
watch(()=>showForm.value || !!deleting.value,async open=>{if(open){dialogOpener=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('.academic-modal input,.academic-modal select,.academic-modal button')?.focus();}else if(dialogOpener?.isConnected)dialogOpener.focus();});
const form=useForm<Row>({});const removal=useForm<Row>({});
const bulk=useForm<Row>({academic_session_id:props.filters.academic_session_id??'',section_id:props.filters.section_id??'',attendance_date:props.filters.attendance_date,exam_schedule_id:props.filters.exam_schedule_id??'',records:props.roster.map(row=>({...row,obtained_marks:row.obtained_marks??''}))});
const action=ref<'publish'|'reopen'>('publish');const actionExam=ref(props.filters.exam_id??'');const publication=useForm({confirm:false,reason:''});
const printPage=()=>window.print();
const tabs=[{page:'student-attendance',label:'Students'},{page:'staff-attendance',label:'Staff'},{page:'reports',label:'Reports'},{page:'timetables',label:'Timetable'},{page:'working-days',label:'Working days'},{page:'periods',label:'Periods'},{page:'examinations',label:'Exams'},{page:'exam-types',label:'Exam types'},{page:'schedules',label:'Schedules'},{page:'marks',label:'Marks'},{page:'grading',label:'Grading'},{page:'results',label:'Results'},{page:'teacher-timetable',label:'Teacher timetable'},{page:'audit',label:'Audit'}];
function filters():Row {return {q:query.value,academic_session_id:session.value,section_id:section.value,academic_class_id:klass.value,teacher_id:teacher.value,student_id:student.value,exam_id:exam.value,exam_schedule_id:schedule.value,attendance_date:date.value,from:from.value,to:to.value,report_type:reportType.value};}
function load(){router.get(`${props.baseUrl}/${props.page}`,filters(),{preserveState:false});}
const exportUrl=computed(()=>props.baseUrl+'/reports/export?'+new URLSearchParams(Object.entries(filters()).filter(([,v])=>v!==''&&v!==null).map(([k,v])=>[k,String(v)])).toString());
const isRoster=computed(()=>['student-attendance','staff-attendance','marks'].includes(props.page));
const marksLocked=computed(()=>props.page==='marks' && props.options.schedules.find(o=>o.id==props.filters.exam_schedule_id)?.locked);
const statuses=computed(()=>props.page==='staff-attendance'?['present','absent','late','leave','holiday']:props.page==='marks'?['scored','absent','exempt']:['present','absent','late','excused']);
const maxMarks=computed(()=>props.options.schedules.find(o=>o.id==props.filters.exam_schedule_id)?.maximum_marks??0);
function allPresent(){for(const row of bulk.records)if(!row.assessed_elsewhere)row.status='present';}
function submitBulk(){bulk.post(`${props.baseUrl}/${props.page}/submit`);}
function defaultBands(){return [{label:'F',minimum_percent:0,maximum_percent:50,is_pass:false},{label:'D',minimum_percent:50,maximum_percent:60,is_pass:true},{label:'C',minimum_percent:60,maximum_percent:70,is_pass:true},{label:'B',minimum_percent:70,maximum_percent:80,is_pass:true},{label:'A',minimum_percent:80,maximum_percent:90,is_pass:true},{label:'A+',minimum_percent:90,maximum_percent:100,is_pass:true}];}
function openForm(row:Row|null=null){editId.value=row?.id??null;const values:Row={};for(const f of props.fields){let value=row?.[f.key]??(f.type==='checkbox'?false:f.options?.[0]??'');if(f.type==='time'&&value)value=String(value).slice(0,5);values[f.key]=value;}if(props.page==='grading'){values.logo_path=row?.logo_path??'/images/school-emblem.svg';values.bands=row?.bands?.map((b:Row)=>({label:b.label,minimum_percent:Number(b.minimum_percent),maximum_percent:Number(b.maximum_percent),is_pass:b.is_pass}))??defaultBands();}if(props.page==='schedules'&&row)values.duration_minutes=(Date.parse('2000-01-01T'+row.ends_at)-Date.parse('2000-01-01T'+row.starts_at))/60000;form.defaults(values);form.reset();form.clearErrors();showForm.value=true;}
function save(){const options={onSuccess:()=>showForm.value=false};if(editId.value)form.put(`${props.baseUrl}/${props.page}/${editId.value}`,options);else form.post(`${props.baseUrl}/${props.page}`,options);}
function remove(){if(deleting.value)removal.delete(`${props.baseUrl}/${props.page}/${deleting.value.id}`,{onSuccess:()=>deleting.value=null});}
function publish(){if(actionExam.value)publication.post(`${props.baseUrl}/results/${actionExam.value}/${action.value}`,{onSuccess:()=>publication.reset()});}
function fieldOptions(f:Field){let values=props.options[f.source??'']??[];if(f.key==='section_id'&&form.academic_class_id)values=values.filter(o=>o.academic_class_id==form.academic_class_id);if(f.key==='teacher_assignment_id')values=values.filter(o=>(!form.academic_session_id||o.academic_session_id==form.academic_session_id)&&(!form.section_id||o.section_id==form.section_id));return values;}
function rowTitle(row:Row){return row.name??row.exam?.name??row.operation??row.section?.academic_class?.name??`Weekday ${row.weekday}`;}
function detail(row:Row){return row.subject?.name??row.timetable_period?.name??row.academic_session?.name??row.code??(row.opens_at?`${row.opens_at} – ${row.closes_at}`:'');}
function focusDialog(event:KeyboardEvent){if(event.key!=='Tab')return;const dialog=event.currentTarget as HTMLElement;const items=Array.from(dialog.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,a[href]'));const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
const weeklyDays=[1,2,3,4,5,6,7]; const dayNames=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
</script>
<template>
<Head :title="title"/>
<DashboardLayout :page="page" :title="title" :schools="schools" :selected-school="selectedSchool" :dashboard="dashboard">
    <div class="academic-local-note no-print"><AppIcon name="shield" :size="15"/><span>LOCAL ACADEMIC OPERATIONS · Database-backed changes · Actor: local development, no authenticated user</span></div>
    <div class="page-heading"><div><h1>{{ title }}</h1><p>{{ selectedSchool?.name }} · Live academic records</p></div><div class="academic-actions no-print"><button v-if="fields.length" class="academic-button" @click="openForm()"><AppIcon name="plus" :size="15"/>Create record</button><button class="secondary-button" @click="printPage"><AppIcon name="receipt" :size="14"/> Print</button></div></div>
    <div v-if="Object.keys(globalErrors).length" class="error-summary no-print" role="alert"><p v-for="error in globalErrors" :key="String(error)">{{ error }}</p></div>
    <div v-if="flash.success" class="success-message no-print" role="status">{{ flash.success }}</div>
    <nav class="academic-tabs no-print" aria-label="Academic operations"><Link v-for="tab in tabs" :key="tab.page" :href="schoolHref(selectedSchool?.slug,tab.page)" :class="{active:page===tab.page || (page==='exams'&&tab.page==='examinations') || (page==='timetable'&&tab.page==='timetables')}">{{ tab.label }}</Link></nav>
    <section class="panel operations-filter-panel no-print"><form class="academic-filters" @submit.prevent="load">
        <label v-if="['periods','grading','exam-types','exams'].includes(page)" class="academic-search"><AppIcon name="search" :size="15"/><input v-model="query" aria-label="Search operations" placeholder="Search name…"/></label>
        <label v-if="!['staff-attendance','periods','working-days','grading','exam-types','audit','results','marks'].includes(page)">Session<select v-model="session" aria-label="Filter academic session"><option value="">All / select session</option><option v-for="o in options.sessions" :key="o.id" :value="o.id">{{ o.label }}</option></select></label>
        <label v-if="['student-attendance','timetable','teacher-timetable','reports','schedules'].includes(page)">Section<select v-model="section" aria-label="Filter section"><option value="">All / select section</option><option v-for="o in options.sections" :key="o.id" :value="o.id">{{ o.label }}</option></select></label>
        <label v-if="['staff-attendance','teacher-timetable','reports'].includes(page)">Teacher<select v-model="teacher" aria-label="Filter teacher"><option value="">All teachers</option><option v-for="o in options.teachers" :key="o.id" :value="o.id">{{ o.label }}</option></select></label>
        <label v-if="['schedules','results','reports'].includes(page)">Exam<select v-model="exam" aria-label="Filter examination"><option value="">All exams</option><option v-for="o in options.exams" :key="o.id" :value="o.id">{{ o.label }}</option></select></label>
        <label v-if="page==='marks'">Examination subject schedule<select v-model="schedule" aria-label="Marks schedule"><option value="">Select schedule</option><option v-for="o in options.schedules" :key="o.id" :value="o.id">{{ o.label }}</option></select></label>
        <label v-if="['student-attendance','staff-attendance'].includes(page)">Attendance date<input v-model="date" type="date" aria-label="Attendance date"/></label>
        <template v-if="page==='reports'"><label>Report<select v-model="reportType" aria-label="Report type"><option v-for="type in ['daily','attendance','monthly','student-history','staff','class-comparison','performance','subject-results','class-results','student-academic','pass-fail','top']" :key="type" :value="type">{{ type.replaceAll('-',' ') }}</option></select></label><label>Class<select v-model="klass" aria-label="Report class"><option value="">All classes</option><option v-for="o in options.classes" :key="o.id" :value="o.id">{{ o.label }}</option></select></label><label>Student<select v-model="student" aria-label="Report student"><option value="">All students</option><option v-for="o in options.students" :key="o.id" :value="o.id">{{ o.label }}</option></select></label><label>From<input v-model="from" type="date" aria-label="Report from"/></label><label>To<input v-model="to" type="date" aria-label="Report to"/></label></template>
        <button class="secondary-button" type="submit">{{ isRoster?'Load roster':'Apply filters' }}</button><a v-if="page==='reports'" :href="exportUrl" class="academic-button">Export CSV</a>
    </form></section>

    <section v-if="isRoster" class="panel roster-panel"><div class="panel-heading"><div><h2>{{ page==='marks'?'Assessment roster':'Daily attendance roster' }}</h2><p>{{ page==='marks'?`Maximum marks: ${maxMarks}. Absent and exempt results must have no numeric marks.`:'Blank means unmarked or unchanged. No student is automatically recorded absent.' }}</p></div><button v-if="page!=='marks' && roster.length" class="secondary-button no-print" @click="allPresent">Set all present</button></div><div v-if="marksLocked" class="academic-local-note">Published results are locked. Open controlled correction from Result Management.</div><form @submit.prevent="submitBulk"><div class="table-scroll"><table><thead><tr><th>Name</th><th>Identifier</th><th>Status</th><template v-if="page==='marks'"><th>Obtained marks</th><th>Teacher remarks</th></template></tr></thead><tbody><tr v-for="(row,i) in bulk.records" :key="row.student_id??row.teacher_id"><td>{{ row.name }}</td><td>{{ row.admission_number??row.identifier }}</td><td><span v-if="row.assessed_elsewhere">Assessed in another section</span><select v-else v-model="row.status" :aria-label="`Status for ${row.name}`" :disabled="marksLocked" @change="page==='marks' && row.status!=='scored' ? row.obtained_marks='' : null"><option value="">Unmarked / unchanged</option><option v-for="status in statuses" :key="status" :value="status">{{ status }}</option></select></td><template v-if="page==='marks'"><td><input v-model="row.obtained_marks" type="number" min="0" :max="maxMarks" step="0.01" :disabled="marksLocked||row.assessed_elsewhere||['absent','exempt'].includes(row.status)" :aria-label="`Marks for ${row.name}`" @input="row.status=row.obtained_marks!==''?'scored':row.status"/></td><td><input v-model="row.remarks" type="text" maxlength="500" :disabled="marksLocked||row.assessed_elsewhere" :aria-label="`Remarks for ${row.name}`"/></td></template></tr></tbody></table></div><div v-if="!roster.length" class="academic-empty"><AppIcon name="students" :size="28"/><h2>No eligible roster loaded</h2><p>Select the session, section and date, or an examination schedule.</p></div><div v-if="Object.keys(bulk.errors).length" class="error-summary" role="alert"><p v-for="error in bulk.errors" :key="error">{{ error }}</p></div><div v-if="roster.length" class="academic-form-footer no-print"><button type="submit" class="academic-button" :disabled="bulk.processing||marksLocked">{{ bulk.processing?'Saving…':'Submit recorded values' }}</button></div></form></section>

    <section v-if="['timetable','teacher-timetable'].includes(page)" class="panel weekly-panel"><div class="panel-heading"><div><h2>Weekly timetable</h2><p>Session-specific schedule · breaks and non-teaching periods included</p></div></div><div class="weekly-grid"><article v-for="day in weeklyDays" :key="day"><h3>{{ dayNames[day-1] }}</h3><div v-for="entry in weekly.filter(e=>e.weekday===day).sort((a,b)=>a.timetable_period.starts_at.localeCompare(b.timetable_period.starts_at))" :key="entry.id" class="weekly-slot" :class="entry.timetable_period.kind"><strong>{{ entry.timetable_period.name }}</strong><time>{{ entry.timetable_period.starts_at.slice(0,5) }}–{{ entry.timetable_period.ends_at.slice(0,5) }}</time><p>{{ entry.section.academic_class.name }} / {{ entry.section.name }}</p><span>{{ entry.teacher_assignment?.subject?.name??entry.timetable_period.kind.replaceAll('_',' ') }}</span><small>{{ entry.teacher_assignment?.teacher?.full_name }}</small></div><p v-if="!weekly.some(e=>e.weekday===day)" class="weekly-empty">No entries</p></article></div></section>

    <section v-if="page==='results'" class="panel publication-panel no-print"><div class="panel-heading"><div><h2>Controlled result publication</h2><p>Mark an examination completed before publication. Reopening keeps every prior report snapshot intact.</p></div></div><form class="publication-form" @submit.prevent="publish"><label>Examination<select v-model="actionExam" aria-label="Publication exam" @change="router.get(`${baseUrl}/results`,{exam_id:actionExam})"><option value="">Select exam</option><option v-for="o in options.exams" :key="o.id" :value="o.id">{{ o.label }} ({{ o.status }})</option></select></label><label>Action<select v-model="action" aria-label="Publication action"><option value="publish">Publish immutable snapshots</option><option value="reopen">Reopen for controlled correction</option></select></label><label v-if="action==='reopen'">Correction reason<textarea v-model="publication.reason" minlength="10" maxlength="500"/></label><label class="publication-confirm"><input v-model="publication.confirm" type="checkbox"/>I confirm this local development publication/correction action.</label><div v-if="Object.keys(publication.errors).length" class="error-summary" role="alert"><p v-for="error in publication.errors" :key="error">{{ error }}</p></div><button class="academic-button" type="submit" :disabled="publication.processing||!actionExam||!publication.confirm">Confirm action</button></form><div v-if="actionExam" class="draft-links"><h3>Draft report previews</h3><Link v-for="s in draftReports" :key="s.student_id" :href="`${baseUrl}/results/${actionExam}/students/${s.student_id}`">{{ s.admission_number }} / {{ s.student_name }}</Link><p>Only students eligible for the selected exam are listed. Missing marks remain unmarked.</p></div></section>

    <template v-if="page==='reports' && reports"><div class="academic-local-note">Daily roster reports require session and section, and include unmarked rows for the selected calendar dates through today. Attendance percentages use (present + late) / (present + late + absent). Excused, leave, holiday and unmarked days are excluded. Examination reports use the latest published snapshot. Dates filter attendance; exam/session filters select published examination reports.</div><div class="report-metrics"><article><span>Matching records</span><strong>{{ reports.total }}</strong></article><article><span>{{ reports.average_percentage!==null?'Average examination percentage':'Recorded attendance rate' }}</span><strong>{{ (reports.average_percentage??reports.summary.percentage)===null?'—':(reports.average_percentage??reports.summary.percentage)+'%' }}</strong></article><article><span>Recorded statuses <template v-if="reports.pass_rate!==null"> ? Pass rate {{ reports.pass_rate }}%</template></span><strong>{{ Object.entries(reports.summary.counts).map(([key,value])=>`${key}: ${value}`).join(' · ')||'No records' }}</strong></article></div><section class="panel report-group-panel"><div class="panel-heading"><h2>Summary by {{ reportType.replaceAll('-',' ') }}</h2></div><div class="table-scroll"><table><thead><tr><th>Group</th><th>Recorded</th><th>Attendance %</th><th>Status counts</th></tr></thead><tbody><tr v-for="group in reports.groups" :key="group.label"><td>{{ group.label }}</td><td>{{ group.recorded }}</td><td>{{ group.percentage??'—' }}</td><td>{{ Object.entries(group.counts).map(([k,v])=>`${k}: ${v}`).join(' / ') }}</td></tr></tbody></table></div></section><section class="panel"><div class="panel-heading"><h2>Recorded detail (first 100 rows; CSV streams all matches)</h2></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Person</th><th>Identifier</th><th>Class / section</th><th>Subject / exam</th><th>Status</th><th>Score</th><th>Grade / rank</th></tr></thead><tbody><tr v-for="(row,i) in reports.rows" :key="i"><td>{{ row.date }}</td><td>{{ row.person }}</td><td>{{ row.identifier }}</td><td>{{ row.class }} / {{ row.section }}</td><td>{{ row.subject }}</td><td>{{ row.status }}</td><td>{{ row.score??'—' }} / {{ row.maximum??'—' }}</td><td>{{ row.grade }} {{ row.rank!==null?`/ ${row.rank}`:'' }}</td></tr></tbody></table></div><p v-if="!reports.total" class="academic-empty">No recorded data matches these filters.</p></section></template>

    <section v-if="rows" class="panel operations-directory"><div class="table-scroll"><table><thead><tr><th>{{ page==='results'?'Student / examination':page==='audit'?'Operation':'Record' }}</th><th>Details</th><th>Status / context</th><th class="no-print">Actions</th></tr></thead><tbody><tr v-for="row in rows.data" :key="row.id"><template v-if="page==='results'"><td><strong>{{ row.snapshot.student_name }}</strong><small>{{ row.snapshot.admission_number }}</small></td><td>{{ row.snapshot.exam_name }} · {{ row.snapshot.percentage??'Exempt' }}{{ row.snapshot.percentage!==null?'%':'' }} · {{ row.snapshot.grade }}</td><td>Published v{{ row.version }} · {{ row.snapshot.outcome }}</td><td class="no-print"><Link class="text-link" :href="`${baseUrl}/report-cards/${row.id}`">View / print report</Link></td></template><template v-else-if="page==='audit'"><td>{{ row.operation }}</td><td>{{ row.entity_type }} #{{ row.entity_id }}<small>{{ row.created_at }}</small></td><td>{{ row.actor_context.mode }}<small>{{ row.reason }}</small></td><td><details><summary>Changes</summary><pre>{{ JSON.stringify(row.changes,null,2) }}</pre></details></td></template><template v-else><td><strong>{{ rowTitle(row) }}</strong><small>{{ detail(row) }}</small></td><td>{{ row.teacher_assignment?.teacher?.full_name ?? row.grading_scheme?.name ?? row.exam_type?.name ?? row.kind ?? '' }} {{ row.exam_date??'' }} {{ row.starts_at??'' }}{{ row.ends_at?'–'+row.ends_at:'' }}</td><td>{{ row.status ?? (row.is_working!==undefined?(row.is_working?'Working':'Closed'):row.ranking_enabled!==undefined?(row.ranking_enabled?'Ranking on':'Ranking off'):'Database') }}<small v-if="row.maximum_marks">Maximum {{ row.maximum_marks }} / pass {{ row.passing_marks }}</small></td><td class="no-print"><div class="row-actions"><button @click="openForm(row)">Edit</button><button class="delete-link" @click="deleting=row">Delete</button></div></td></template></tr></tbody></table></div><div v-if="!rows.data.length" class="academic-empty"><AppIcon name="academics" :size="28"/><h2>No records yet</h2><p>Create a record or adjust your filters.</p></div><div class="academic-pagination no-print"><span>{{ rows.total }} records</span><nav aria-label="Pagination"><template v-for="(link,i) in rows.links" :key="i"><Link v-if="link.url" :href="link.url" :class="{active:link.active}" v-html="link.label"/><span v-else v-html="link.label"/></template></nav></div></section>

    <div v-if="showForm" class="academic-modal-overlay no-print" @keydown.esc.stop="showForm=false"><section class="academic-modal operations-modal" role="dialog" aria-modal="true" aria-labelledby="operation-form-title" @keydown="focusDialog"><h2 id="operation-form-title">{{ editId?'Edit':'Create' }} {{ title }}</h2><form @submit.prevent="save" novalidate><div class="academic-form-grid"><div v-for="f in fields" :key="f.key" class="form-field" :class="{'checkbox-field':f.type==='checkbox'}"><label :for="'op-'+f.key">{{ f.label }}</label><input v-if="f.type==='checkbox'" :id="'op-'+f.key" v-model="form[f.key]" type="checkbox"/><select v-else-if="f.type==='select'" :id="'op-'+f.key" v-model="form[f.key]"><option value="">Select / not assigned</option><option v-for="o in f.options" :key="o" :value="o">{{ o.replaceAll('_',' ') }}</option><option v-for="o in fieldOptions(f)" :key="o.id" :value="o.id">{{ o.label }}</option></select><input v-else :id="'op-'+f.key" v-model="form[f.key]" :type="f.type" :step="f.type==='number'?'0.01':undefined"/><p v-if="form.errors[f.key]" class="field-error">{{ form.errors[f.key] }}</p></div></div><div v-if="page==='grading'" class="grading-editor"><h3>Grading bands</h3><p>Cover 0–100 without gaps. Lower bounds are inclusive; upper bounds are exclusive except 100.</p><div class="table-scroll"><table><thead><tr><th>Grade</th><th>Minimum %</th><th>Maximum %</th><th>Pass</th><th>Remove</th></tr></thead><tbody><tr v-for="(band,i) in form.bands" :key="i"><td><input v-model="band.label" :aria-label="`Grade label ${Number(i)+1}`" maxlength="20"/></td><td><input v-model="band.minimum_percent" type="number" min="0" max="100" step="0.01" :aria-label="`Minimum grade ${Number(i)+1}`"/></td><td><input v-model="band.maximum_percent" type="number" min="0" max="100" step="0.01" :aria-label="`Maximum grade ${Number(i)+1}`"/></td><td><input v-model="band.is_pass" type="checkbox" :aria-label="`Passing grade ${Number(i)+1}`"/></td><td><button class="delete-link" type="button" @click="form.bands.splice(Number(i),1)">Remove</button></td></tr></tbody></table></div><button type="button" class="secondary-button" @click="form.bands.push({label:'',minimum_percent:0,maximum_percent:100,is_pass:true})">Add band</button></div><div v-if="Object.keys(form.errors).length" class="error-summary" role="alert"><p v-for="error in form.errors" :key="error">{{ error }}</p></div><div class="academic-form-footer"><button type="button" class="secondary-button" @click="showForm=false">Cancel</button><button type="submit" class="academic-button" :disabled="form.processing">{{ form.processing?'Saving…':'Save record' }}</button></div></form></section></div>
    <div v-if="deleting" class="academic-modal-overlay no-print" @keydown.esc.stop="deleting=null"><section class="academic-modal" role="dialog" aria-modal="true" aria-labelledby="operation-delete-title" @keydown="focusDialog"><h2 id="operation-delete-title">Delete unused record?</h2><p>Dependent schedules, marks, published results and historical records cannot be removed through this action.</p><div v-if="Object.keys(removal.errors).length" class="error-summary" role="alert"><p v-for="error in removal.errors" :key="error">{{ error }}</p></div><div class="academic-actions"><button class="secondary-button" @click="deleting=null">Cancel</button><button class="danger-button" :disabled="removal.processing" @click="remove">Confirm delete</button></div></section></div>
</DashboardLayout>
</template>
